        await analytics.trackAnonymousEvent<ITestEvent>("jest_test_event", {
            foo: "bar",
        });
        expect(fakePosthog.capture.mock.calls[0][0]).toBe("jest_test_event");
        expect(fakePosthog.capture.mock.calls[0][1]).toEqual({ foo: "bar" });
    });

    it("Should pass trackRoomEvent to posthog", async () => {
        await analytics.init(Anonymity.Pseudonymous);
        const roomId = "42";
        await analytics.trackRoomEvent<IRoomEvent>("jest_test_event", roomId, {
            foo: "bar",
        });
        expect(fakePosthog.capture.mock.calls[0][0]).toBe("jest_test_event");
        expect(fakePosthog.capture.mock.calls[0][1]).toEqual({
            foo: "bar",
            hashedRoomId: "73475cb40a568e8da8a045ced110137e159f890ac4da883b6b17dc651b3a8049",
        });
    });

    it("silently ignores tracking while disabled", async () => {
        await analytics.trackAnonymousEvent<ITestEvent>("jest_test_event", {
            foo: "bar",
        });
        await analytics.trackPseudonymousEvent<ITestEvent>("jest_test_event", { foo: "bar" });
        await analytics.trackRoomEvent<ITestRoomEvent>("jest_test_room_event", "42", { foo: "bar" });
        expect(fakePosthog.capture.mock.calls.length).toBe(0);
    });

    it("does not track pseudonymous events in anonymous mode", async () => {
        await analytics.init(Anonymity.Anonymous);
        await analytics.trackPseudonymousEvent<ITestEvent>("jest_test_event", {
            foo: "bar",
        });
        expect(fakePosthog.capture.mock.calls.length).toBe(0);
    });

    it("identifies the user with a SHA-256 digest in pseudonymous mode", async () => {
        await analytics.init(Anonymity.Pseudonymous);
        await analytics.identifyUser("foo");
        expect(fakePosthog.identify.mock.calls[0][0])
            .toBe("2c26b46b68ffc68ff99b453c1d30413413422d706483bfa0f98a5e886266e7ae");
    });

    it("does not identify the user in anonymous mode", async () => {
        await analytics.init(Anonymity.Anonymous);
        await analytics.identifyUser("foo");
        expect(fakePosthog.identify.mock.calls.length).toBe(0);
    });

    it("does not identify a user while disabled", async () => {
        analytics.setAnonymity(Anonymity.Pseudonymous);
        await analytics.identifyUser("foo");
        expect(fakePosthog.identify).not.toHaveBeenCalled();
    });

    it("rejects capture while enabled but initialization is pending", async () => {
        let finishInit: () => void;
        fakePosthog.init.mockImplementation(() => new Promise<void>((resolve) => { finishInit = resolve; }));
        const initializing = analytics.init(Anonymity.Pseudonymous);
        await new Promise((resolve) => setTimeout(resolve, 0));
        expect(fakePosthog.init).toHaveBeenCalled();
        expect(analytics.isEnabled()).toBe(true);
        expect(analytics.isInitialised()).toBe(false);
        await expect(analytics.trackAnonymousEvent<ITestEvent>("jest_test_event", { foo: "bar" }))
            .rejects.toThrow();
        expect(fakePosthog.capture).not.toHaveBeenCalled();
        finishInit();
        await initializing;
    });

    it("awaits capture completion for all three tracking methods", async () => {
        await analytics.init(Anonymity.Pseudonymous);
        const trackingMethods = [
            () => analytics.trackAnonymousEvent<ITestEvent>("jest_test_event", { foo: "bar" }),
            () => analytics.trackPseudonymousEvent<ITestEvent>("jest_test_event", { foo: "bar" }),
            () => analytics.trackRoomEvent<ITestRoomEvent>("jest_test_room_event", "42", { foo: "bar" }),
        ];

        for (const track of trackingMethods) {
            fakePosthog.capture.mockReset();
            let finishCapture: () => void;
            let captureStarted: () => void;
            const started = new Promise<void>((resolve) => { captureStarted = resolve; });
            fakePosthog.capture.mockImplementation(() => {
                captureStarted();
                return new Promise<void>((resolve) => { finishCapture = resolve; });
            });
            let completed = false;
            const tracking = track().then(() => { completed = true; });
            await started;
            expect(fakePosthog.capture).toHaveBeenCalledTimes(1);
            expect(completed).toBe(false);
            finishCapture();
            await tracking;
            expect(completed).toBe(true);
        }
    });

    it("sends a null room hash when no room ID is given", async () => {
        await analytics.init(Anonymity.Pseudonymous);
        await analytics.trackRoomEvent<ITestRoomEvent>("jest_test_room_event", null, { foo: "bar" });
        expect(fakePosthog.capture).toHaveBeenCalledWith(
            "jest_test_room_event", { foo: "bar", hashedRoomId: null });
    });

    it("does not emit room events in anonymous mode", async () => {
        await analytics.init(Anonymity.Anonymous);
        await analytics.trackRoomEvent<ITestRoomEvent>("jest_test_room_event", "42", { foo: "bar" });
        expect(fakePosthog.capture).not.toHaveBeenCalled();
    });

    it("changes event gating with the anonymity setter", async () => {
        await analytics.init(Anonymity.Anonymous);
        analytics.setAnonymity(Anonymity.Pseudonymous);
        expect(analytics.getAnonymity()).toBe(Anonymity.Pseudonymous);
        await analytics.trackPseudonymousEvent<ITestEvent>("jest_test_event", { foo: "bar" });
        analytics.setAnonymity(Anonymity.Anonymous);
        await analytics.trackPseudonymousEvent<ITestEvent>("jest_test_event", { foo: "baz" });
        expect(fakePosthog.capture).toHaveBeenCalledTimes(1);
    });

    it("resets PostHog and returns to anonymous mode on logout", async () => {
        await analytics.init(Anonymity.Pseudonymous);
        analytics.logout();
        expect(fakePosthog.reset).toHaveBeenCalledTimes(1);
        expect(analytics.getAnonymity()).toBe(Anonymity.Anonymous);
        await analytics.trackPseudonymousEvent<ITestEvent>("jest_test_event", { foo: "bar" });
        expect(fakePosthog.capture).not.toHaveBeenCalled();
    });

    it("does not reset PostHog when logout occurs while disabled", () => {
        analytics.setAnonymity(Anonymity.Pseudonymous);
        analytics.logout();
        expect(fakePosthog.reset).not.toHaveBeenCalled();
        expect(analytics.getAnonymity()).toBe(Anonymity.Anonymous);
    });

    it("sanitises the current URL and referrer using the current anonymity mode", async () => {
        window.location.hash = "#/register/some";
        await analytics.init(Anonymity.Anonymous);
        const sanitize = fakePosthog.init.mock.calls[0][1].sanitize_properties;
        const properties = {
            '$current_url': "https://private.example/path",
            '$referrer': "https://private.example/previous",
            '$device_id': "private-device-id",
        };
        const anonymous = sanitize({ ...properties }, "test");
        expect(anonymous['$current_url']).toBe(`${window.location.origin}${window.location.pathname}#/register/<redacted>`);
        expect(anonymous['$referrer']).toBeNull();
        expect(anonymous['$device_id']).toBeNull();

        analytics.setAnonymity(Anonymity.Pseudonymous);
        await analytics.trackAnonymousEvent<ITestEvent>("jest_test_event", { foo: "bar" });
        const pseudonymous = sanitize({ ...properties }, "test");
        expect(pseudonymous['$current_url']).toBe(
            `${window.location.origin}${window.location.pathname}#/register/`
            + "a6b46dd0d1ae5e86cbc8f37e75ceeb6760230c1ca4ffbcb0c97b96dd7d9c464b",
        );
        expect(pseudonymous['$referrer']).toBe(properties['$referrer']);
        expect(pseudonymous['$device_id']).toBe(properties['$device_id']);
    });

    it("Should pseudonymise a location of a known screen", async () => {
        const location = await getRedactedCurrentLocation(
            "https://foo.bar", "#/register/some/pii", "/", Anonymity.Pseudonymous);
        expect(location).toBe(
            `https://foo.bar/#/register/\
a6b46dd0d1ae5e86cbc8f37e75ceeb6760230c1ca4ffbcb0c97b96dd7d9c464b/\
bd75b3e080945674c0351f75e0db33d1e90986fa07b318ea7edf776f5eef38d4`);
    });

    it("Should anonymise a location of a known screen", async () => {
        const location = await getRedactedCurrentLocation(
            "https://foo.bar", "#/register/some/pii", "/", Anonymity.Anonymous);
        expect(location).toBe("https://foo.bar/#/register/<redacted>/<redacted>");
    });

    it("Should pseudonymise a location of an unknown screen", async () => {
        const location = await getRedactedCurrentLocation(
            "https://foo.bar", "#/not_a_screen_name/some/pii", "/", Anonymity.Pseudonymous);
        expect(location).toBe(
            `https://foo.bar/#/<redacted_screen_name>/\
a6b46dd0d1ae5e86cbc8f37e75ceeb6760230c1ca4ffbcb0c97b96dd7d9c464b/\
bd75b3e080945674c0351f75e0db33d1e90986fa07b318ea7edf776f5eef38d4`);
    });

    it("Should anonymise a location of an unknown screen", async () => {
        const location = await getRedactedCurrentLocation(
            "https://foo.bar", "#/not_a_screen_name/some/pii", "/", Anonymity.Anonymous);
        expect(location).toBe("https://foo.bar/#/<redacted_screen_name>/<redacted>/<redacted>");
    });
});

